package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var reportTmpl *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	// Template for rendering report pages
	reportTmpl = template.Must(template.New("report").Parse(`
		<html><body>
		<h1>Report: {{.Title}}</h1>
		<div>{{.Content}}</div>
		<p>Generated for: {{.Username}}</p>
		</body></html>
	`))
}

type Report struct {
	Title    string
	Content  string
	Username string
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func getReportHandler(w http.ResponseWriter, r *http.Request) {
	reportID := r.URL.Query().Get("id")
	format := r.URL.Query().Get("format")

	if reportID == "" {
		http.Error(w, "missing id", 400)
		return
	}

	// Validate format parameter
	if format != "" && format != "json" && format != "html" {
		http.Error(w, "invalid format", 400)
		return
	}
	if format == "" {
		format = "json"
	}

	// Fetch report - parameterized query, safe
	var title, content, username string
	err := db.QueryRow("SELECT title, content, username FROM reports WHERE id = $1", reportID).Scan(&title, &content, &username)
	if err != nil {
		http.Error(w, "not found", 404)
		return
	}

	if format == "json" {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(Report{Title: title, Content: content, Username: username})
	} else {
		w.Header().Set("Content-Type", "text/html")
		reportTmpl.Execute(w, Report{Title: title, Content: content, Username: username})
	}
}

func searchReportsHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	sortBy := r.URL.Query().Get("sort")

	if query == "" {
		http.Error(w, "missing query", 400)
		return
	}

	// Build search query - sort parameter is vulnerable to injection
	allowedSorts := map[string]bool{"title": true, "created_at": true, "username": true}
	orderClause := "created_at DESC"
	if sortBy != "" {
		// Developer intended to validate but used wrong check
		if strings.Contains(sortBy, " ") {
			// Block obvious multi-word injections... but not all
			_ = allowedSorts // unused, developer forgot to actually check
			orderClause = "created_at DESC"
		} else {
			orderClause = sortBy
		}
	}

	var whereClause string
	var args []interface{}
	if category != "" {
		whereClause = "WHERE content ILIKE $1 AND category = $2"
		args = []interface{}{"%" + query + "%", category}
	} else {
		whereClause = "WHERE content ILIKE $1"
		args = []interface{}{"%" + query + "%"}
	}

	sqlQuery := fmt.Sprintf("SELECT id, title, username FROM reports %s ORDER BY %s LIMIT 20", whereClause, orderClause)
	rows, err := db.Query(sqlQuery, args...)
	if err != nil {
		http.Error(w, "query error", 500)
		return
	}
	defer rows.Close()

	type Result struct {
		ID    int    `json:"id"`
		Title string `json:"title"`
		User  string `json:"user"`
	}
	var results []Result
	for rows.Next() {
		var r Result
		rows.Scan(&r.ID, &r.Title, &r.User)
		results = append(results, r)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func main() {
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/api/reports", getReportHandler)
	http.HandleFunc("/api/reports/search", searchReportsHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
